def count_special_quadruplets(nums):
    from collections import Counter
    answer=0
    right=Counter()
    for b in range(len(nums)-3,0,-1):
        for d in range(b+2,len(nums)):
            right[nums[d]-nums[b+1]]+=1
        for a in range(b):
            answer+=right[nums[a]+nums[b]]
    return answer

